using System.Diagnostics;using System.Runtime.InteropServices;using System.Text;namespace NexaShareControl.Native;internal record WindowRecord(long WindowId,string ProcessName,string Title,int X,int Y,int Width,int Height,bool IsVisible,bool IsMinimized);internal static class WindowControl{delegate bool E(IntPtr h,IntPtr l);[StructLayout(LayoutKind.Sequential)]struct R{public int L,T,Rt,B;}[DllImport("user32.dll")]static extern bool EnumWindows(E e,IntPtr l);[DllImport("user32.dll")]static extern bool IsWindowVisible(IntPtr h);[DllImport("user32.dll")]static extern bool IsIconic(IntPtr h);[DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern int GetWindowText(IntPtr h,StringBuilder b,int c);[DllImport("user32.dll")]static extern bool GetWindowRect(IntPtr h,out R r);[DllImport("user32.dll")]static extern uint GetWindowThreadProcessId(IntPtr h,out uint p);[DllImport("user32.dll")]static extern bool SetForegroundWindow(IntPtr h);[DllImport("user32.dll")]static extern bool ShowWindow(IntPtr h,int c);[DllImport("user32.dll")]static extern IntPtr GetForegroundWindow();public static List<WindowRecord>ListWindows(){var l=new List<WindowRecord>();EnumWindows((h,_)=>{if(!IsWindowVisible(h))return true;var b=new StringBuilder(2048);GetWindowText(h,b,b.Capacity);var t=b.ToString();if(string.IsNullOrWhiteSpace(t))return true;GetWindowRect(h,out var r);GetWindowThreadProcessId(h,out uint pid);string p="";try{p=Process.GetProcessById((int)pid).ProcessName;}catch{}l.Add(new(h.ToInt64(),p,t,r.L,r.T,r.Rt-r.L,r.B-r.T,true,IsIconic(h)));return true;},IntPtr.Zero);return l.OrderBy(x=>x.ProcessName).ThenBy(x=>x.Title).ToList();}public static bool Activate(IntPtr h){if(h==IntPtr.Zero)return false;if(IsIconic(h))ShowWindow(h,9);return SetForegroundWindow(h);}public static WindowRecord?GetActive(){var h=GetForegroundWindow();return ListWindows().FirstOrDefault(w=>w.WindowId==h.ToInt64());}}
